{
  "title": "The Rescue of the Lantern Prince",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "A distant view of the broken capital at dusk.",
      "visual_description": "Wide shot of a ruined royal city silhouetted against a violet sky, collapsed spires and tattered banners catching the last light.",
      "characters": ["Captain Aelra"]
    },
    {
      "scene_number": 2,
      "caption": "The rescue party meets at the old waystone.",
      "visual_description": "Four figures gather around a moss-covered stone marker at the edge of a pine wood, unrolling a hand-drawn map by lantern light.",
      "characters": ["Captain Aelra", "Mira the Pathfinder", "Brennic the Hedge-Mage", "Old Tomwin"]
    },
    {
      "scene_number": 3,
      "caption": "Mira studies the map of the fallen city.",
      "visual_description": "Close-up of weathered hands tracing inked streets on parchment, candle flame flickering across symbols of towers and gates.",
      "characters": ["Mira the Pathfinder"]
    },
    {
      "scene_number": 4,
      "caption": "They approach the broken castle gates.",
      "visual_description": "Massive iron-banded gates hang crooked off their hinges, the royal crest split down the middle, weeds growing through the cobblestones.",
      "characters": ["Captain Aelra", "Mira the Pathfinder", "Brennic the Hedge-Mage", "Old Tomwin"]
    },
    {
      "scene_number": 5,
      "caption": "A frightened townswoman warns them away.",
      "visual_description": "A woman in a soot-streaked shawl clutches a child's hand in a doorway, eyes wide, gesturing back toward the dark streets.",
      "characters": ["Captain Aelra", "Goodwife Hesta"]
    },
    {
      "scene_number": 6,
      "caption": "Armored patrols march down the main avenue.",
      "visual_description": "A column of black-plated soldiers moves in lockstep past shuttered shops, torchlight glinting off helms shaped like snarling wolves.",
      "characters": ["Mira the Pathfinder", "Iron Patrol Sergeant"]
    },
    {
      "scene_number": 7,
      "caption": "The party hides in a collapsed bakery.",
      "visual_description": "Four figures press against a flour-dusted wall behind a broken oven, shadows of marching boots passing across a shattered window.",
      "characters": ["Captain Aelra", "Mira the Pathfinder", "Brennic the Hedge-Mage", "Old Tomwin"]
    },
    {
      "scene_number": 8,
      "caption": "Old Tomwin dozes off at the worst moment.",
      "visual_description": "An elderly man in court robes snores softly against a sack of grain while the others glare, a half-eaten apple in his lap.",
      "characters": ["Old Tomwin", "Captain Aelra"]
    },
    {
      "scene_number": 9,
      "caption": "Rumors of a dragon drift through the alleys.",
      "visual_description": "Two ragged street children whisper under a torn royal banner, pointing at distant scorch marks streaking a tower wall.",
      "characters": ["Brennic the Hedge-Mage", "Pip the Urchin", "Wren the Urchin"]
    },
    {
      "scene_number": 10,
      "caption": "They reach the foot of the cursed tower.",
      "visual_description": "A leaning black tower wreathed in pale green mist, runes glowing faintly along cracked stones, crows circling overhead.",
      "characters": ["Captain Aelra", "Mira the Pathfinder", "Brennic the Hedge-Mage", "Old Tomwin"]
    },
    {
      "scene_number": 11,
      "caption": "Brennic deciphers the wards on the door.",
      "visual_description": "A robed mage presses both palms against an iron-bound door covered in shifting silver glyphs, his breath fogging in the cold air.",
      "characters": ["Brennic the Hedge-Mage"]
    },
    {
      "scene_number": 12,
      "caption": "The magic door swings open in silence.",
      "visual_description": "The heavy door eases inward revealing a spiral staircase lit by floating blue motes, dust drifting in the threshold.",
      "characters": ["Brennic the Hedge-Mage", "Captain Aelra"]
    },
    {
      "scene_number": 13,
      "caption": "They climb past tattered royal banners.",
      "visual_description": "A narrow stairwell hung with faded crimson banners bearing a golden stag, the cloth shredded and stirring in an unfelt wind.",
      "characters": ["Captain Aelra", "Mira the Pathfinder", "Brennic the Hedge-Mage", "Old Tomwin"]
    },
    {
      "scene_number": 14,
      "caption": "They find the prince locked in a glass cell.",
      "visual_description": "A pale young man in a torn velvet doublet sits inside a tall crystalline cylinder, palms pressed to the glass, a small lantern at his feet.",
      "characters": ["Prince Calen", "Captain Aelra", "Brennic the Hedge-Mage"]
    },
    {
      "scene_number": 15,
      "caption": "An alarm horn sounds across the city.",
      "visual_description": "View from a tower window: red signal fires bloom on distant rooftops while armored figures pour into the streets below.",
      "characters": ["Mira the Pathfinder", "Prince Calen"]
    },
    {
      "scene_number": 16,
      "caption": "They flee down a back stair into the sewers.",
      "visual_description": "Five figures splash through ankle-deep water in a vaulted brick tunnel, Brennic's staff glowing pale blue, rats scattering ahead.",
      "characters": ["Captain Aelra", "Mira the Pathfinder", "Brennic the Hedge-Mage", "Old Tomwin", "Prince Calen"]
    },
    {
      "scene_number": 17,
      "caption": "Tomwin holds the gatehouse winch alone.",
      "visual_description": "The old courtier braces against a massive wooden crank in a stone gatehouse, sweat on his brow, an arrow embedded in the beam beside him.",
      "characters": ["Old Tomwin", "Iron Patrol Sergeant"]
    },
    {
      "scene_number": 18,
      "caption": "The party escapes across the river bridge at dawn.",
      "visual_description": "A long stone bridge over a mist-filled gorge, four figures running toward the sunrise as the city burns red behind them.",
      "characters": ["Captain Aelra", "Mira the Pathfinder", "Brennic the Hedge-Mage", "Prince Calen"]
    }
  ]
}

